extern pure comb: int -> int -> int = math.comb
let row n = List.range 0 (n + 1) |> List.map (comb n)
print (row 7)

let squares =
  seq {
    for x in List.range 1 6:
      let y = x * x
      yield y
  }
squares |> Seq.map (fun n -> n + 1) |> Seq.take 5 |> Seq.toList |> print
Seq.initInfinite (fun i -> i * 5) |> Seq.filter (fun n -> n % 2 == 0) |> Seq.take 5 |> Seq.toList |> print

let parseEntry line =
  option {
    let! v = String.split "=" line |> List.get 1
    let! n = String.toInt (String.strip v)
    return n * 3
  }
let inputs = ["bo=16", "dee=x", "kit = 0", "cy=5=1"]
let results = List.map parseEntry inputs
List.iter print results
print (results |> List.map (Option.withDefault 0) |> List.sum)
print (results |> List.map (Option.map (fun n -> n + 1)) |> List.filter Option.isSome |> List.len)

let pure discount price qty = price * qty - 7 * qty
let report label price qty =
  print f"{label}: {discount price qty}"
  discount price qty
let overall = [("pin", 28, 4), ("pin", 48, 2), ("nut", 21, 1), ("pin", 26, 5)] |> List.map (fun (n, pr, q) -> report n pr q) |> List.sum
print overall
